begin;

on conflict (id) do update set name = excluded.name, emoji = excluded.emoji, sort_order = excluded.sort_order;

on conflict (id) do update set name = excluded.name, description = excluded.description, price = excluded.price, category_id = excluded.category_id, image = excluded.image, emoji = excluded.emoji, available = excluded.available, featured = excluded.featured, popular = excluded.popular, options = excluded.options;

on conflict (id) do update set restaurant_name = excluded.restaurant_name, tagline = excluded.tagline, phone = excluded.phone, email = excluded.email, address = excluded.address, opening_hours = excluded.opening_hours, delivery_fee = excluded.delivery_fee, free_delivery_over = excluded.free_delivery_over;

commit;
